<section class='dashboard-content'><div class='dashboard-heading'><div class='eyebrow'>نمونه‌کار</div><h1>نمونه‌کارهای من</h1><a class='button' href='<?=url('/portfolio/create')?>'>افزودن نمونه‌کار</a></div><section class='dash-card'><div class='freelancer-grid'><?php foreach(($portfolios??[]) as $portfolio): ?><article class='freelancer-item'><h3><?=e($portfolio['title']??'نمونه‌کار')?></h3><p><?=e($portfolio['description']??'')?></p><details><summary class="text-link">ویرایش</summary><form method="post" action="<?=url('/portfolio/update')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($portfolio['id'])?>"><input name="title" required value="<?=e($portfolio['title']??'')?>"><textarea name="description" required><?=e($portfolio['description']??'')?></textarea><input name="technologies" value="<?=e($portfolio['technologies']??'')?>" placeholder="تکنولوژی‌ها"><input name="project_url" value="<?=e($portfolio['project_url']??'')?>" placeholder="لینک پروژه"><input name="github_url" value="<?=e($portfolio['github_url']??'')?>" placeholder="GitHub"><input name="project_result" value="<?=e($portfolio['project_result']??'')?>" placeholder="نتیجه پروژه"><button class="button button-small">ذخیره ویرایش</button></form></details><form method="post" action="<?=url('/portfolio/delete')?>" onsubmit="return confirm('حذف نمونه‌کار؟')"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($portfolio['id'])?>"><button class="action-button suspend">حذف</button></form></article><?php endforeach; ?><?php if(empty($portfolios)): ?><p class='muted'>هنوز نمونه‌کاری ایجاد نکرده‌اید.</p><?php endif; ?></div></section></section>